2	 * Tiny, dependency-free pagination helper shared by the admin tables.
3	 *
4	 * Given the (already-awaited) searchParams and a total row count, it clamps the
5	 * requested `?page=` into range and returns the Prisma `skip`/`take` window plus
6	 * the resolved page number and total page count for rendering controls.
7	 *
8	 * Not a Server Action — a plain synchronous helper, safe to import anywhere.
9	 */
10	export type PageInfo = {
11	  skip: number;
12	  take: number;
13	  page: number;
14	  pages: number;
15	  perPage: number;
16	  total: number;
17	};
18	
19	export function paginate(
20	  searchParams: { page?: string | string[] } | undefined,
21	  total: number,
22	  perPage = 25
23	): PageInfo {
24	  const per = Math.max(1, Math.floor(perPage) || 25);
25	  const pages = Math.max(1, Math.ceil(Math.max(0, total) / per));
26	
27	  const rawParam = Array.isArray(searchParams?.page)
28	    ? searchParams?.page[0]
29	    : searchParams?.page;
30	  const raw = Number(rawParam ?? 1);
31	  const requested = Number.isFinite(raw) ? Math.floor(raw) : 1;
32	  const page = Math.min(Math.max(1, requested), pages);
33	
34	  return { skip: (page - 1) * per, take: per, page, pages, perPage: per, total };
35	}
