import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { InvoiceStatusBadge } from "@/components/customer/InvoiceViews";
import { RegenerateMissingButton } from "@/components/admin/InvoiceAdmin";
import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
import { bulkVoidInvoices } from "@/lib/actions-admin-billing";
import { formatInvoiceNumber, invoiceBranding } from "@/lib/invoices";
import { paginate, pageHref } from "@/lib/pagination";
import type { InvoiceStatus } from "@prisma/client";

export const dynamic = "force-dynamic";

const STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];
const PER_PAGE = 25;

export default async function AdminInvoices({
  searchParams,
}: {
  searchParams: Promise<{ status?: string; page?: string }>;
}) {
  await requireArea("billing");
  const sp = await searchParams;
  const status = STATUSES.includes(sp.status as InvoiceStatus)
    ? (sp.status as InvoiceStatus)
    : undefined;
  const where = status ? { status } : {};

  const [total, issued, paid, outstanding] = await Promise.all([
    db.invoice.count({ where }),
    db.invoice.aggregate({ where: { status: { not: "VOID" } }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "PAID" }, _sum: { amountCents: true } }),
    db.invoice.aggregate({ where: { status: "OPEN" }, _sum: { amountCents: true } }),
  ]);

  const pg = paginate(sp, total, PER_PAGE);
  const invoices = await db.invoice.findMany({
    where,
    include: { user: { select: { id: true, email: true, name: true } } },
    orderBy: { createdAt: "desc" },
    skip: pg.skip,
    take: pg.take,
  });

  const chip = (href: string, label: string, active: boolean) => (
    <Link
      href={href}
      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
        active
          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
      }`}
    >
      {label}
    </Link>
  );

  const exportHref = `/api/admin/export?type=invoices${status ? `&status=${status}` : ""}`;
  const filterParams = { status };

  // One settings read for the whole page; the prefix is per-platform, not per-invoice.
  const { numberPrefix } = await invoiceBranding();

  const rows: BulkRow[] = invoices.map((inv) => ({
    id: inv.id,
    // Only OPEN/REFUNDED invoices can be bulk-voided.
    selectable: inv.status === "OPEN" || inv.status === "REFUNDED",
    cells: [
      <Link key="n" href={`/admin/invoices/${inv.id}`} className="font-mono text-xs text-slate-300 hover:text-brand-300">
        {formatInvoiceNumber(inv.number, numberPrefix)}
      </Link>,
      <Link key="c" href={`/admin/users/${inv.user.id}`} className="hover:text-brand-300">
        {inv.user.email}
      </Link>,
      <Link key="d" href={`/admin/invoices/${inv.id}`} className="block max-w-xs truncate hover:text-brand-300">
        {inv.description}
      </Link>,
      <InvoiceStatusBadge key="s" status={inv.status} />,
      <span key="a" className="font-mono">{fmtMoney(inv.amountCents)}</span>,
      <span key="t" className="text-xs text-slate-400" title={inv.createdAt.toISOString()}>
        {timeAgo(inv.createdAt)}
      </span>,
    ],
  }));

  return (
    <div className="space-y-6">
      <PageHeader title="Invoices" sub="All billing documents issued across the platform.">
        <Link href="/admin/billing" className="btn-ghost py-1.5">
          Billing
        </Link>
        <RegenerateMissingButton />
      </PageHeader>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Issued · total" value={fmtMoney(issued._sum.amountCents ?? 0)} delta="excl. void" />
        <StatCard label="Paid" value={fmtMoney(paid._sum.amountCents ?? 0)} />
        <StatCard label="Outstanding" value={fmtMoney(outstanding._sum.amountCents ?? 0)} delta="open" deltaGood={false} />
        <StatCard label="Count" value={String(total)} delta={status ? `filtered: ${status.toLowerCase()}` : "all statuses"} />
      </div>

      <div className="card p-0">
        <div className="flex flex-wrap items-center justify-end gap-2 px-5 pt-5">
          {chip("/admin/invoices", "All", !status)}
          {STATUSES.map((s) =>
            chip(`/admin/invoices?status=${s}`, s.charAt(0) + s.slice(1).toLowerCase(), status === s)
          )}
        </div>

        <BulkTable
          columns={[
            { header: "Number" },
            { header: "Client" },
            { header: "Description" },
            { header: "Status" },
            { header: "Amount", className: "text-right" },
            { header: "Issued", className: "text-right" },
          ]}
          rows={rows}
          exportHref={exportHref}
          minWidth={760}
          empty="No invoices found."
          actions={[
            {
              label: "Void",
              danger: true,
              confirm: "Void the selected open invoices? They will no longer be collectible.",
              run: bulkVoidInvoices,
            },
          ]}
        />

        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
          <span>
            Page {pg.page} of {pg.pages} · {total} invoice{total === 1 ? "" : "s"}
          </span>
          <div className="flex items-center gap-2">
            {pg.page > 1 && (
              <Link href={pageHref("/admin/invoices", filterParams, pg.page - 1)} className="btn-ghost py-1 text-xs">
                ← Prev
              </Link>
            )}
            {pg.page < pg.pages && (
              <Link href={pageHref("/admin/invoices", filterParams, pg.page + 1)} className="btn-ghost py-1 text-xs">
                Next →
              </Link>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import type { FeedDir, FeedKind } from "@/lib/analytics";

/**
 * Date-range + source + sort controls for the visitor "Traffic feed". State
 * lives entirely in the URL query string (from/to/kind/dir), so the server
 * component re-queries on navigation and the filter is shareable/bookmarkable.
 * A plain form: no data fetching here, just router.push of the chosen params.
 */
export function TrafficFeedFilter({
  from,
  to,
  kind,
  dir,
}: {
  from: string;
  to: string;
  kind: FeedKind;
  dir: FeedDir;
}) {
  const router = useRouter();
  const sp = useSearchParams();
  const [f, setF] = useState(from);
  const [t, setT] = useState(to);
  const [k, setK] = useState<FeedKind>(kind);
  const [d, setD] = useState<FeedDir>(dir);

  function apply() {
    const params = new URLSearchParams(sp.toString());
    const set = (key: string, val: string) => (val ? params.set(key, val) : params.delete(key));
    set("from", f);
    set("to", t);
    set("kind", k === "all" ? "" : k);
    set("dir", d === "desc" ? "" : d);
    const qs = params.toString();
    router.push(qs ? `/admin/visitors?${qs}` : "/admin/visitors");
  }

  function clear() {
    setF(""); setT(""); setK("all"); setD("desc");
    router.push("/admin/visitors");
  }

  const dirty = f !== from || t !== to || k !== kind || d !== dir;
  const anyFilter = from || to || kind !== "all" || dir !== "desc";

  return (
    <div className="card space-y-3">
      <div className="flex items-center justify-between">
        <p className="text-sm font-semibold text-white">Filter by date</p>
        <span className="text-xs text-slate-500">sort the traffic feed by an explicit range</span>
      </div>
      <div className="flex flex-wrap items-end gap-3">
        <label className="flex flex-col gap-1 text-xs text-slate-400">
          From
          <input
            type="date"
            className="input text-sm"
            value={f}
            max={t || undefined}
            onChange={(e) => setF(e.target.value)}
          />
        </label>
        <label className="flex flex-col gap-1 text-xs text-slate-400">
          To
          <input
            type="date"
            className="input text-sm"
            value={t}
            min={f || undefined}
            onChange={(e) => setT(e.target.value)}
          />
        </label>
        <label className="flex flex-col gap-1 text-xs text-slate-400">
          Source
          <select className="input text-sm" value={k} onChange={(e) => setK(e.target.value as FeedKind)}>
            <option value="all">All traffic</option>
            <option value="marketing">Marketing site</option>
            <option value="portal">Portal</option>
          </select>
        </label>
        <label className="flex flex-col gap-1 text-xs text-slate-400">
          Sort
          <select className="input text-sm" value={d} onChange={(e) => setD(e.target.value as FeedDir)}>
            <option value="desc">Newest first</option>
            <option value="asc">Oldest first</option>
          </select>
        </label>
        <button className="btn-secondary text-sm" disabled={!dirty} onClick={apply}>
          Apply
        </button>
        {anyFilter && (
          <button className="text-sm text-slate-400 hover:text-red-400" onClick={clear}>
            Clear
          </button>
        )}
      </div>
    </div>
  );
}

